  "implementation": "def solve(case):
    nodes = case["nodes"]
    core = case["core_distance"]
    distances = case["distances"]

    # Build edges with mutual reachability distance
    edges = []
    for u, v, d in distances:
        w = max(core[u], core[v], d)
        edges.append((u, v, w))

    # Union-Find data structure
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        xr, yr = find(x), find(y)
        if xr == yr:
            return False
        if rank[xr] < rank[yr]:
            parent[xr] = yr
        elif rank[xr] > rank[yr]:
            parent[yr] = xr
        else:
            parent[yr] = xr
            rank[xr] += 1
        return True

    # Kruskal's algorithm
    edges.sort(key=lambda e: e[2])
    mst_edges = []
    total_weight = 0.0
    for u, v, w in edges:
        if union(u, v):
            mst_edges.append([u, v, w])
            total_weight += w

    return {"mst_edges": mst_edges, "total_weight": total_weight}
